/* ==========================================================================
        /* Keep plugin subtree shrinkable inside QAM flex layout (avoids horizontal spill). */
        /*
          Do not set overflow-x on .bonsai-scope: if overflow-x is not visible, CSS forces overflow-y
          away from visible, which clipped tab content below the icon strip. Horizontal containment
          stays on TabContentsScroll + width/min-width fixes on bleed/ask rows.
        */
        .bonsai-scope {
          width: 100%;
          max-width: 100%;
          min-width: 0;
          box-sizing: border-box;
          /* Explicit 0: rows must reach the QAM edges, and an inherited inset here would shift
             every full-bleed row at once (the "no longer span QAM width" bug). */
          padding-left: 0;
          padding-right: 0;
          /* Fill QAM column height so Decky Tabs body is not crushed into the ~80px strip row. */
          display: flex;
          flex-direction: column;
          flex: 1 1 auto;
          min-height: 0;
          align-self: stretch;
          overflow: hidden;
        }

        /* Durable QAM height lock (inline height on scope is wiped by React/Decky re-renders). */
        .bonsai-scope.bonsai-qam-height-locked {
          height: var(--bonsai-qam-lock-height) !important;
          min-height: var(--bonsai-qam-lock-height) !important;
          max-height: var(--bonsai-qam-lock-height) !important;
          display: flex !important;
          flex-direction: column !important;
          overflow: hidden !important;
          box-sizing: border-box !important;
        }

        /*
          Decky wraps plugin content in .decky-qam-scope. On Bazzite gamescope, pointer entry can
          collapse that host to tab-strip height (~80px); stretch it with the plugin column.
        */
        .decky-qam-scope:has(> .bonsai-scope) {
          display: flex !important;
          flex-direction: column !important;
          flex: 1 1 auto !important;
          min-height: 0 !important;
          align-self: stretch !important;
          width: 100% !important;
          box-sizing: border-box !important;
          /* Decky's wrapper is the last ancestor bonsAI can name, and any horizontal padding it
             carries insets every row at once. Scoped by :has so no other plugin's panel changes. */
          padding-left: 0 !important;
          padding-right: 0 !important;
        }
        .bonsai-scope .bonsai-settings-connection-row {
          min-width: 0;
          max-width: 100%;
        }
        .bonsai-scope .bonsai-settings-connection-host input {
          min-width: 0 !important;
          max-width: 100%;
        }

        /* Non-main tabs: clip horizontal paint overflow without touching Main full-bleed (shell only). */
        .bonsai-scope .bonsai-tab-panel-shell--tight {
          width: 100%;
          max-width: 100%;
          min-width: 0;
          box-sizing: border-box;
          overflow-x: hidden;
        }

        /* Flushes row content with PanelSection title (counters default row inset). */
        .bonsai-scope .bonsai-settings-bleed {
          box-sizing: border-box;
          width: 100%;
          max-width: 100%;
          margin-left: calc(-1 * (calc(0px * var(--bonsai-ui-scale, 1))));
          margin-right: calc(-1 * (calc(0px * var(--bonsai-ui-scale, 1))));
          padding-left: calc(0px * var(--bonsai-ui-scale, 1));
          padding-right: calc(0px * var(--bonsai-ui-scale, 1));
        }

        .bonsai-scope .bonsai-settings-section-stack {
          display: flex;
          flex-direction: column;
          gap: 1.5rem;
          font-size: calc(14px * var(--bonsai-ui-scale, 1)) !important;
          line-height: 1.4 !important;
        }

        /*
          Explicit prose hooks: Deck CEF often ignored inherited overflow-wrap on PanelSection subtrees
          (class names do not always match our [class*="PanelSection"] patterns). H6 fix.
        */
        .bonsai-scope .bonsai-prose-host {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          box-sizing: border-box !important;
        }
        .bonsai-scope .bonsai-prose {
          display: block !important;
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          box-sizing: border-box !important;
          white-space: normal !important;
          overflow-wrap: anywhere !important;
          word-wrap: break-word !important;
          word-break: break-word !important;
          font-size: calc(12px * var(--bonsai-ui-scale, 1)) !important;
          line-height: 1.4 !important;
        }

        /* Settings action buttons: shrink Focusable host so gpfocus ring hugs the button. */
        .bonsai-scope .bonsai-settings-focus-btn-host {
          width: 100%;
          display: flex;
          flex-direction: column;
          align-items: flex-start;
        }
        .bonsai-scope .bonsai-settings-focus-btn-host > .Panel.Focusable,
        .bonsai-scope .bonsai-settings-focus-btn-host > .Focusable {
          width: auto !important;
          max-width: 100% !important;
          flex: 0 0 auto !important;
        }
        .bonsai-scope button.bonsai-settings-focus-btn.gpfocus,
        .bonsai-scope button.bonsai-settings-focus-btn:focus-visible {
          outline: 2px solid rgba(255, 255, 255, 0.88) !important;
          outline-offset: 2px !important;
          box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.45) !important;
        }
        .bonsai-scope .bonsai-settings-focus-btn-host > .Panel.Focusable.gpfocus,
        .bonsai-scope .bonsai-settings-focus-btn-host > .Panel.Focusable:focus-visible {
          outline: none !important;
          box-shadow: none !important;
        }


/* ==========================================================================
           1. DECKY TAB HOST (do not kill transitions — Steam's tab carousel uses them to slide).
           ========================================================================== */

        /* Tab host: column flex so tab body grows below the strip (Bazzite gamescope kept host ≈80px).
           Do not flex-grow the carousel strip row itself — only TabContentsScroll (section 3). */
        .bonsai-scope .bonsai-decky-tabs-root {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          min-height: 0 !important;
          box-sizing: border-box !important;
          /* Both axes must say clip. Per spec, clip on one axis computes to hidden when the
             other axis is hidden — measured on device 2026-08-07: this rule read back as
             hidden/hidden for as long as it was written as overflow-x only. hidden still
             allows *programmatic* scrolling, which is what made the strip flicker (see the
             sibling rule below). */
          overflow: clip !important;
          display: flex !important;
          flex-direction: column !important;
          flex: 1 1 0% !important;
          align-self: stretch !important;
        }

        /* Decky Tabs host between strip and TabContentsScroll must shrink, not grow with content.

           clip, not hidden — this is the LB/RB tab-strip flicker fix (TAB-SWITCH-01).
           Measured on device 2026-08-07: on an RB press this wrapper's scrollWidth transiently
           inflates (300 -> 420) while the outgoing tab is still mounted, Steam scrolls it right
           to reveal the incoming tab, and then the browser clamps scrollLeft back down frame by
           frame as scrollWidth collapses — dragging the whole strip sideways and back over
           ~350ms. scrollLeft tracked scrollWidth - clientWidth exactly on every frame. LB never
           showed it because scrolling toward 0 is valid at any scrollWidth.

           overflow:hidden does not prevent this: a hidden box is still a scroll container and
           is still scrollable programmatically (measured: scrollLeft took 119.53 under hidden, 0
           under clip). clip removes the scroll container outright, so there is no offset to
           clamp. This element has no legitimate scroll range to lose — at rest it measures
           scrollWidth == clientWidth == 300; the carousel's real horizontal scrolling happens on
           a deeper Steam element (sw 362 / cw 188), which this rule does not touch. */
        .bonsai-scope .bonsai-decky-tabs-root > .Panel,
        .bonsai-scope .bonsai-decky-tabs-root > div {
          flex: 1 1 0% !important;
          min-height: 0 !important;
          min-width: 0 !important;
          display: flex !important;
          flex-direction: column !important;
          overflow: clip !important;
          align-self: stretch !important;
        }

        .bonsai-scope .bonsai-decky-tabs-root [class*="TabContentsScroll"] {
          position: relative !important;
          z-index: 1 !important;
          flex: 1 1 0% !important;
          min-height: 0 !important;
          max-height: 100% !important;
          overflow-y: auto !important;
        }

        /* Plan 30 (D44): Steam's tab header — LB hint, icon carousel, RB hint — is hidden; the
           collapsing bar above the tabs root shows the tab instead. Structural and hash-free: the
           header wrapper is the Tabs panel's first child, the only child holding our title leaves
           and both aria-labelled hint images and not TabContentsScroll (probe_deck_tab_bar.py,
           2026-09-02). display:none, not height:0 + visibility:hidden — measured the same day:
           both leave Steam's hidden tab button as a D-pad stop (its nav tree is mounted
           Focusables, not layout), but only display:none takes the leaves out of layout, so
           useTabStripBodyOffset does not reserve their 62px (variant B reserved 67px and reclaimed
           nothing). Fail-safe by construction: if a Steam update stops this from matching, Steam's
           own strip reappears above our bar and nothing else breaks. Steam keeps handling LB/RB
           with the row hidden — TAB-BAR-W1a, with and without a game running. */
        .bonsai-scope .bonsai-decky-tabs-root > .Panel.Focusable > div:has(.bonsai-tab-title-leaf):has(img[aria-label]):not(:has([class*="TabContentsScroll"])) {
          display: none !important;
        }

        /*
          Plan 30 W6 (2026-09-02): everything that used to style Steam's tab strip here — the leaf
          box, the icon shells and sizes, the dim and bright rings, the icon drop-shadows and the
          [data-bonsai-active-tab] marker — was deleted. Steam's header is display:none (the rule
          above), so none of it could paint, and docs/audit/decky-tab-strip-classes.md had already
          recorded the .Active-keyed ring blocks as dead since 2026-08-04. The strip's job moved to
          TabIndicatorBar + styles/sections/tabIndicatorBar.ts. data-bonsai-active-tab stays on the
          tabs root: nothing styles on it any more, but the on-Deck rows read it as the probe of
          which tab is active (runs/TAB-BAR-03-*.json expect on it).
        */

        .bonsai-scope [class*="TabContentsScroll"] {
          scroll-behavior: auto !important;
          overflow-x: hidden !important;
          overflow-y: auto !important;
          min-width: 0 !important;
          max-width: 100% !important;
        }


/* ==========================================================================
           2. TAB CAROUSEL LAYOUT (THE "GHOST NUDGE" FIX)
           ========================================================================== */
        .bonsai-scope .bonsai-tab-title-shell {
          display: flex !important;
          justify-content: center !important;
          align-items: center !important;
          width: auto !important;
          min-width: 0 !important;
          max-width: none !important;
          height: auto !important;
          text-transform: none !important;

          margin: 0 !important;
          padding: 0 !important;
        }

        .bonsai-scope .bonsai-tab-title-icon {
          display: flex !important;
          align-items: center !important;
          justify-content: center !important;
          margin: 0 !important;
          padding: 0 !important;
          line-height: 0;
          text-transform: none !important;
        }


/* ==========================================================================
           3. GENERAL SPACING & WIDTH RESETS
           Groups and removes Steam's default padding/margins on scroll areas and panels
           to allow true full-bleed layouts across the entire plugin.
           ========================================================================== */
        /*
          WARNING: every [class*="PanelSection"] / [class*="PanelSectionRow"] selector in this file
          matches NOTHING on the shipping Deck build. Measured 2026-08-16 with
          scripts/probe_deck_ask_row_width.py: 0 matches inside the QAM, because Steam hashes those
          class names (the PanelSection wrapping Main's rows is "_3gY0aBuNR8_NPTpXIYfkby").
          "_TabContentsScroll" survives as a literal, which is why only that reset actually applies.

          Do not assume these rules are doing anything; the padding reset below silently was not,
          which is what left a 16px gutter on both sides of every Main row (see section-4.ts, where
          the working fix reaches the same element by structure via :has). They are kept because
          other Steam builds do ship readable names — but anything load-bearing needs a structural
          selector or a probe run to confirm it matches.
        */
        .bonsai-scope [class*="TabContentsScroll"],
        .bonsai-scope [class*="TabContentsScroll"] > div,
        .bonsai-scope [class*="PanelSection"] {
          margin-top: 0 !important;
          padding-top: 0 !important;
          padding-left: 0 !important;
          padding-right: 0 !important;
          min-width: 0 !important;
        }

        /* After the global TabContentsScroll reset: gap under LB/RB strip + kill stray horizontal inset
           (Deck screenshots: SETTINGS body looked right-shifted vs panel edge). */
        .bonsai-scope.bonsai-qam-height-locked .bonsai-decky-tabs-root [class*="TabContentsScroll"] {
          height: var(--bonsai-tab-body-height, auto) !important;
          max-height: var(--bonsai-tab-body-height, 100%) !important;
          flex: 0 0 auto !important;
          overflow-y: auto !important;
        }

        .bonsai-scope .bonsai-decky-tabs-root [class*="TabContentsScroll"] {
          margin-top: var(--bonsai-tab-strip-reserve, 0px) !important;
          padding-top: 0 !important;
          position: relative !important;
          top: auto !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          padding-left: calc(0px * var(--bonsai-ui-scale, 1)) !important;
          padding-right: calc(0px * var(--bonsai-ui-scale, 1)) !important;
          box-sizing: border-box !important;
          flex: 1 1 0% !important;
          min-height: 0 !important;
          max-height: 100% !important;
          overflow-y: auto !important;
          align-self: stretch !important;
        }

        .bonsai-scope .bonsai-decky-tabs-root [class*="TabContentsScroll"] > div {
          margin-left: 0 !important;
          margin-right: 0 !important;
          padding-left: 0 !important;
          padding-right: 0 !important;
          width: 100% !important;
          max-width: 100% !important;
          box-sizing: border-box !important;
          align-self: stretch !important;
          /* H5: Deck sometimes makes this a flex column with align-items:flex-end — whole body hugs the right. */
          display: flex !important;
          flex-direction: column !important;
          align-items: stretch !important;
          justify-content: flex-start !important;
        }

        .bonsai-scope .bonsai-decky-tabs-root [class*="TabContentsScroll"] > div [class*="PanelSection"] {
          display: flex !important;
          flex-direction: column !important;
          align-items: stretch !important;
          align-self: stretch !important;
          width: 100% !important;
          max-width: 100% !important;
        }

        /*
          LB/RB bumper tab switches use Steam's native carousel and can flash when tab content
          hosts animate. Keep icon-strip transitions; suppress only the content pane motion.
        */
        .bonsai-scope .bonsai-decky-tabs-root [class*="TabContentsScroll"],
        .bonsai-scope .bonsai-decky-tabs-root [class*="TabContentsScroll"] > div {
          transition: none !important;
          animation: none !important;
        }

        .bonsai-scope .bonsai-decky-tabs-root [class*="PanelSectionRow"] {
          justify-content: flex-start !important;
          align-self: stretch !important;
          width: 100% !important;
        }

        /*
          Panel copy was still painting past the QAM edge (Deck screenshot): long lines need explicit
          wrapping + shrink in nested flex; overflow-wrap:anywhere breaks tokens if needed.
        */
        .bonsai-scope [class*="PanelSection"],
        .bonsai-scope [class*="PanelSectionRow"],
        .bonsai-scope [class*="PanelSectionRow"] > div {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          overflow-wrap: anywhere !important;
          word-wrap: break-word !important;
        }

        .bonsai-scope [class*="PanelSectionRow"] {
          margin-top: 0 !important;
          margin-bottom: 0 !important;
          overflow: visible !important;
          align-self: stretch !important;
        }

        .bonsai-scope .Panel.Focusable { height: auto !important; }
        .bonsai-scope .Panel.Focusable > div { position: relative !important; top: 0 !important; }


/* ==========================================================================
           4. FULL-BLEED & ASKBAR WRAPPERS
           Forces specific containers to break out of standard bounds for edge-to-edge UI.
           ========================================================================== */
        /*
          Row width tracks the tab scroll area; side inset lives on TabContentsScroll (BONSAI_PLUGIN_SIDE_PAD_PX).
          Do not use negative margins here — they cancel the scroll inset and hug the QAM edge.
        */
        .bonsai-scope .bonsai-full-bleed-row,
        .bonsai-scope .bonsai-ask-bleed-wrap.bonsai-full-bleed-row {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          padding-left: 0 !important;
          padding-right: 0 !important;
          box-sizing: border-box !important;
        }

        /* Main unified search + Ask row: stay within tab scroll width (no calc bleed spill). */
        .bonsai-scope .bonsai-unified-input-host.bonsai-full-bleed-row,
        .bonsai-scope .bonsai-preset-row-host.bonsai-full-bleed-row {
          width: 100% !important;
          max-width: 100% !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          padding-left: 0 !important;
          padding-right: 0 !important;
        }

        .bonsai-scope .bonsai-unified-input-host.bonsai-full-bleed-row {
          margin-bottom: calc(2px * var(--bonsai-ui-scale, 1)) !important;
        }

        /*
          Reach the PanelSection by structure, because its name cannot be matched on this build.

          Measured on device 2026-08-16 (scripts/probe_deck_ask_row_width.py): inside the QAM,
          `[class*="PanelSection"]` matches **0 elements** and `.decky-qam-scope` does not exist —
          Steam ships hashed class names here (the PanelSection wrapping our rows is
          `_3gY0aBuNR8_NPTpXIYfkby`), so every section-3 rule keyed on those names is inert. Only
          `_TabContentsScroll` survives as a literal, which is why that one reset does work.

          That PanelSection carries `padding: 0 16px`, and it was the entire remaining gutter —
          probe V1 reported 15.99px on each side, against a 300px QAM column. Rows opting into
          full bleed must not inherit it.

          Matches the row wrapper holding a full-bleed row, and the section holding that
          wrapper. :has() is verified supported on the Deck's CEF in the same run. Keyed on
          .bonsai-full-bleed-row so only rows that asked for edge-to-edge are affected — other
          tabs do not use that class.

          The .bonsai-main-tab-column line: the Main tab wraps its rows in a fill column + bottom
          dock (useMainTabColumnFill), which puts the PanelSection two divs further from its
          full-bleed rows — out of range of both :has() patterns below. Without this line the
          section's 16px side padding comes back on Main only, which is exactly the original bug.
        */
        .bonsai-scope div:has(> .bonsai-full-bleed-row),
        .bonsai-scope div:has(> div > .bonsai-full-bleed-row),
        .bonsai-scope div:has(> .bonsai-main-tab-column) {
          padding-left: 0 !important;
          padding-right: 0 !important;
        }

        /* padding-bottom: 5px for the chip's soft shadow to land in (2026-09-17: there was no room
           at all; file header, point 1). The negative margin leaves the dock's one row gap between
           chip and question box, the same as under the box (plan 72); the box covers the rest. */
        .bonsai-scope .bonsai-preset-row-host {
          min-width: 0 !important;
          overflow: hidden !important;
          display: grid !important;
          gap: 8px !important;
          margin-top: 0 !important;
          padding-top: 0 !important;
          padding-bottom: 5px !important;
          margin-bottom: calc(calc(2px * var(--bonsai-ui-scale, 1)) - 5px) !important;
        }

        /* Fade mode had 12px under its chips; since plan 72 it has the same row gap as every mode. */
        .bonsai-scope .bonsai-preset-row-host--fade-anim {
          gap: 3px !important;
          margin-bottom: calc(calc(2px * var(--bonsai-ui-scale, 1)) - 5px) !important;
          margin-top: 0 !important;
        }

        /*
          One chip. Height and side padding are set here on purpose, not left to Steam's DialogButton
          default: with two chips across a 300px column (D43, 2026-09-01) the label room is what
          decides whether a prompt reads at a glance, and a width that comes from CSS can be reasoned
          about (design-language rule 4) where Steam's padding could only be measured after the fact.
          The drawing (major-redesign.md § 2.3) says 30px tall, radius 4.
        */
        .bonsai-scope button.bonsai-preset-glass {
          max-width: 100% !important;
          min-width: 0 !important;
          overflow: hidden !important;
          box-sizing: border-box !important;
          min-height: 30px !important;
          height: 30px !important;
          padding: 0 8px !important;
          border-radius: 4px !important;
          display: flex !important;
          align-items: center !important;
          justify-content: flex-start !important;
          line-height: 1.2 !important;
        }
        .bonsai-scope button.bonsai-preset-glass > div {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          overflow: hidden !important;
          display: flex !important;
          align-items: center !important;
        }
        /*
          The label is a row: badges pinned at the left, then the prompt text. The text either
          scrolls (Steam's Marquee, which brings its own overflow handling and edge fade) or, when
          the Marquee is unavailable or motion is reduced, is cut off with an ellipsis. The ellipsis
          fallback is display:block on purpose — on the old display:inline span `overflow` did not
          apply, the ellipsis could never fire, and a 59-character label simply ran 86px past the
          column edge (measured on device 2026-08-29).
        */
        .bonsai-scope button.bonsai-preset-glass .bonsai-preset-chip-label {
          display: flex !important;
          align-items: center !important;
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          overflow: hidden !important;
          white-space: nowrap !important;
          text-align: left !important;
        }
        .bonsai-scope button.bonsai-preset-glass .bonsai-preset-chip-test-badge,
        .bonsai-scope button.bonsai-preset-glass .bonsai-preset-chip-tip-badge {
          flex: 0 0 auto !important;
        }
        .bonsai-scope button.bonsai-preset-glass .bonsai-preset-chip-text {
          flex: 1 1 auto !important;
          min-width: 0 !important;
          max-width: 100% !important;
        }
        .bonsai-scope button.bonsai-preset-glass .bonsai-preset-chip-text:not(.bonsai-preset-chip-text--marquee) {
          display: block !important;
          overflow: hidden !important;
          text-overflow: ellipsis !important;
          white-space: nowrap !important;
        }
        /*
          Decode mode (Ghost in the Shell chip decode -- replaces the old `stream` typewriter).
          The reveal loop in MainTabPresetAnimatedChips.tsx writes scrambled/resolving glyphs and
          the blinking block caret straight into the label's textContent from a single shared
          requestAnimationFrame loop, so there is no CSS keyframe to gate here -- reduced motion is
          enforced entirely in JS (instant swap to the final prompt, no churn, no caret).
          Plan 60, board B (D110, item 6) used to tint the whole label with
          `--bonsai-ui-accent-toned` here, but the selector never said "still churning" -- it
          stayed on the label whether resolved or not, so a decode chip's words read in the same
          accent family as its Tip dot (maintainer bug report, 2026-09-19; only the dot should carry
          that colour). Removed: DecodePresetChipButton now sets the label colour inline instead,
          the same `#c4d3e2` every other mode already uses (PresetChipButton below).
        */

        .bonsai-scope .bonsai-chat-response-stack {
          margin-top: calc(12px * var(--bonsai-ui-scale, 1)) !important;
        }

        .bonsai-scope .bonsai-preset-carousel-focus-root {
          width: 100% !important;
          min-width: 0 !important;
        }
        /*
          Chips side by side: PRESET_VISIBLE_SLOTS across one row, equal shares, a small gap. Two
          rather than the drawing's three by decision D43 (2026-09-01): on the 300px column three
          left ~12 characters per chip and two leave ~20. The row keeps the one-row height that the
          2026-08-31 change bought (the block used to be three stacked rows, 118px of a 245px dock).
          Width comes from flex, never from a measurement (design-language rule 4).
        */
        .bonsai-scope .bonsai-preset-across {
          display: flex !important;
          flex-direction: row !important;
          gap: 6px !important;
          width: 100% !important;
          min-width: 0 !important;
        }
        .bonsai-scope .bonsai-preset-across > .bonsai-preset-carousel-slot {
          flex: 1 1 0 !important;
          min-width: 0 !important;
        }
        /*
          Sideways carousel. The track holds the whole history (up to five chips) as a flex row and
          the viewport clips it to one row's width; the chips outside the window are simply clipped
          and still focusable, so a D-pad step onto one slides it into view. Each chip is an equal
          share of the viewport, and the slide is a calc on the window-start index the component
          writes to --bonsai-preset-window-start: one step is (100% + gap) / N, which is exactly one
          chip plus one gap for any N. No pixel is ever measured.
        */
        /* This viewport hides anything outside itself too, so it clips the shadow in carousel mode
           even after the row above gained room: 5px given, the same 5px taken back off its height,
           so the shadow shows and nothing on screen moves. */
        .bonsai-scope .bonsai-preset-carousel-viewport {
          width: 100% !important;
          min-width: 0 !important;
          overflow: hidden !important;
          padding-bottom: 5px !important;
          margin-bottom: -5px !important;
        }
        .bonsai-scope .bonsai-preset-carousel-track {
          display: flex !important;
          flex-direction: row !important;
          gap: 6px !important;
          width: 100% !important;
          min-width: 0 !important;
          will-change: transform !important;
          /*
            --bonsai-preset-visible-slots lets the "one suggestion chip" setting override the
            window width per render (MainTabPresetAnimatedChips writes it alongside
            --bonsai-preset-window-start); the fallback is PRESET_VISIBLE_SLOTS, the shipped
            default, for the rare case nothing wrote the variable.
          */
          transform: translateX(
            calc(-1 * var(--bonsai-preset-window-start, 0) * (100% + 6px) / var(--bonsai-preset-visible-slots, 2))
          ) !important;
        }
        .bonsai-scope .bonsai-preset-carousel-track > .bonsai-preset-carousel-slot {
          flex: 0 0 calc((100% - 6px * (var(--bonsai-preset-visible-slots, 2) - 1)) / var(--bonsai-preset-visible-slots, 2)) !important;
          min-width: 0 !important;
        }
        /*
          The lit bar under the chip the D-pad is on. It marks which chip a press would act on, and
          it must never appear on a chip the D-pad has left: ungated, the old version of this sat on
          a chip permanently, so with the D-pad up on the tab strip the screen still showed a
          highlighted chip — the fake focus ring found on device 2026-08-28, which fooled the
          maintainer and the QA rig at once. The gates are unchanged and exist for that reason.

          Gate 1 and 2 say "the carousel owns Steam's ring": `gpfocuswithin` is what Steam stamps on
          the ancestor Focusable, and the `:has(.gpfocus)` arm covers it directly in case Steam
          stamps only the chip. Gate 3 keeps the marker on desktop, in the in-IDE preview and on
          touch, where nothing owns a ring — the fallback `elementHasGamepadFocus` uses in
          uiDocument.ts. The last two arms light the rows whose slots carry no --focus marker at
          all (fade, static and decode), which get the same bar.

          2026-09-17 (plan 60) changed what these gates draw, not when. See the file header,
          point 2: the blue line round the chip became a lit bar inside its bottom edge, and the
          hairline and drop shadow are repeated in the list because box-shadow replaces rather than
          adds. `outline: none` stops Steam's plain focus outline showing up clipped in its place.
        */
        .bonsai-scope .bonsai-preset-carousel-focus-root.gpfocuswithin .bonsai-preset-carousel-slot--focus .bonsai-preset-glass,
        .bonsai-scope .bonsai-preset-carousel-focus-root:has(.gpfocus) .bonsai-preset-carousel-slot--focus .bonsai-preset-glass,
        :root:not(:has(.gpfocus)) .bonsai-scope .bonsai-preset-carousel-slot--focus .bonsai-preset-glass,
        .bonsai-scope button.bonsai-preset-glass.gpfocus,
        :root:not(:has(.gpfocus)) .bonsai-scope button.bonsai-preset-glass:focus-visible {
          outline: none !important;
          box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.10), inset 0 -2px 0 rgba(56, 189, 248, 0.55), 0 2px 3px rgba(0, 0, 0, 0.4) !important; /* alpha toned 0.85->0.55, 2026-09-19, too bright */
        }
        /* The label brightens with the bar, so the whole chip reads as the live one. Decode used to
           be excluded here (its label owned its own colour); that rule is gone (bug fix
           2026-09-19), so a focused decode chip now brightens like every other mode. */
        .bonsai-scope .bonsai-preset-carousel-focus-root.gpfocuswithin .bonsai-preset-carousel-slot--focus .bonsai-preset-glass .bonsai-preset-chip-label,
        .bonsai-scope .bonsai-preset-carousel-focus-root:has(.gpfocus) .bonsai-preset-carousel-slot--focus .bonsai-preset-glass .bonsai-preset-chip-label,
        :root:not(:has(.gpfocus)) .bonsai-scope .bonsai-preset-carousel-slot--focus .bonsai-preset-glass .bonsai-preset-chip-label,
        .bonsai-scope button.bonsai-preset-glass.gpfocus .bonsai-preset-chip-label,
        :root:not(:has(.gpfocus)) .bonsai-scope button.bonsai-preset-glass:focus-visible .bonsai-preset-chip-label {
          color: #dcebf8 !important;
        }

        /*
          The "ran out of chips" edge cue (roadmap [chips], filed 2026-09-04). Left/Right already
          claims the move at both row edges without moving anything (presetRowNav.ts's
          onBlockedEdge, called only when the press was claimed-and-blocked, never when a pinned
          batch pulled a new entry in) so Steam's own idea of "past the end" -- the Quick Access
          rail -- never fires; the gap this closes is that the claimed-and-blocked press looked
          identical on screen to a stall. usePresetRowNav (MainTabPresetAnimatedChips.tsx) flags the
          one chip that claimed a blocked press with this class for
          PRESET_CHIP_BLOCKED_EDGE_FLASH_MS, then clears it. Same cyan family as the other
          focus-adjacent glows here and in gamepadAndPullModels.ts, so it is not a new colour.

          Since 2026-09-17 (plan 60) the cue lives on the same bottom bar the focused chip already
          shows: the bar flares brighter with a soft cyan glow under it, then settles back. Before,
          it recoloured the border, which was the old focus marker, so the flash and the focus cue
          looked alike. All four effects are repeated in one list because box-shadow replaces rather
          than adds. No transform and no width change, so the chip's own box never grows. The long
          first arm is not decoration, and this rule must stay below the bar rules: file header,
          points 2 and 3.

          A plain transition, not @keyframes: section-6.ts's base `.bonsai-preset-glass` rule sets
          its own `box-shadow: ... !important`, and an animation cannot out-rank a static !important
          declaration (only a transition can). It lives on this modifier rule alone, so removing the
          class removes the transition and cannot touch the carousel's own dimmed/undimmed fade.
        */
        .bonsai-scope .bonsai-preset-carousel-focus-root .bonsai-preset-carousel-slot button.bonsai-preset-glass.bonsai-preset-chip-blocked-edge,
        .bonsai-scope button.bonsai-preset-glass.bonsai-preset-chip-blocked-edge {
          transition: box-shadow 144ms ease-out;
          box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.10), inset 0 -2px 0 rgba(150, 225, 255, 1), 0 3px 8px -2px rgba(56, 189, 248, 0.55), 0 2px 3px rgba(0, 0, 0, 0.4) !important;
        }
        /* Reduced motion: no ramp, just the same glow held for the same window and then removed
           by the JS timeout -- a state change, not movement. Same two arms as above, scoped to the
           flagged chip alone so it cannot silence any other control's transition. */
        @media (prefers-reduced-motion: reduce) {
          .bonsai-scope .bonsai-preset-carousel-focus-root .bonsai-preset-carousel-slot button.bonsai-preset-glass.bonsai-preset-chip-blocked-edge,
          .bonsai-scope button.bonsai-preset-glass.bonsai-preset-chip-blocked-edge {
            transition: none !important;
          }
        }

        /*
          The settings-results card (plan 45 / plan 56 lane E). Positioned by the component itself
          (position: absolute; bottom: 100% of the box's own wrapper) — this only draws it, on the
          same horizontal track as the box so it lines up with the textarea above which it floats.
          Sized by its own content: MainTabUnifiedAskBar.tsx decides how many rows to render (never
          more than fit the live-measured room above it), and the card simply stacks whatever it is
          given. The heading-to-row-1 gap comes from the heading's own padding-bottom below, not
          from this card's row gap, so the two never double up — see settingsCardHeightForRows in
          useSteamSettingsSearch.ts, which this file's numbers are read from directly.
        */
        .bonsai-scope .bonsai-settings-results-card {
          width: 100% !important;
          max-width: none !important;
          min-width: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          box-sizing: border-box !important;
          display: flex;
          flex-direction: column;
          border-radius: 8px;
          padding: 6px 6px 6px;
          pointer-events: auto;
          z-index: 5;
        }
        /*
          A card floating over the chat needs its own solid surface — the transcript behind it is
          not opaque (the same reason the dock itself carries an explicit background, section-6.ts).
          Measured on the Deck 2026-09-16 (build ca12429, screenshots/DeckCapture_20260916_045914_game.png):
          a chat slot title and a reply's own text both still read straight through the card at the
          previous 0.92 alpha, over both the heading and rows four and five. Fully opaque now, not
          just "mostly" — an alpha channel of any size leaves room for a CEF compositing surprise
          like that one to show through again, and there is nothing behind this card worth blending
          with. ".bonsai-settings-results-card.bonsai-glass-panel" is three class selectors, one more
          than the shared ".bonsai-glass-panel" rule above (section-6.ts) that supplies the 0.25
          fallback every other glass panel uses, so this rule already outranks it on specificity
          alone (section-4.test.ts pins that count) — the blur is turned off here too, on its own
          !important rule, since the shared blur rule (section-6.ts) carries none at all and a blur
          has nothing left to do once the surface behind it can never show through regardless.
        */
        .bonsai-scope .bonsai-settings-results-card.bonsai-glass-panel {
          background: rgb(18, 26, 34) !important;
          backdrop-filter: none !important;
          -webkit-backdrop-filter: none !important;
        }
        .bonsai-scope .bonsai-settings-results-card-heading {
          color: #8fa8c4;
          font-size: 11px;
          line-height: 16px;
          padding-bottom: 6px;
        }
        .bonsai-scope .bonsai-settings-results-card-heading-count {
          color: #6b7c90;
        }
        .bonsai-scope .bonsai-settings-results-card-row {
          flex-shrink: 0;
        }
        .bonsai-scope .bonsai-settings-results-card-row + .bonsai-settings-results-card-row {
          margin-top: 2px;
        }

        /*
          The Ask row is a sibling PanelSectionRow of the unified input host in the same column, so
          100% on both makes them the same width by construction.

          It used to be a measured pixel snapshot instead (--bonsai-askbar-outer-width, set from
          host width in useUnifiedInputSurface, plus a --bonsai-ask-margin-left correction). That
          made the Ask row the only row that could not follow the panel: a sample taken mid-carousel,
          at first paint, or before a padding change settled froze it narrower than its neighbours,
          which is the "Ask bar no longer spans QAM width" bug. Both vars are gone — do not
          reintroduce a px width here.
        */
        .bonsai-scope .bonsai-ask-bleed-wrap.bonsai-full-bleed-row {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
        }

        /* H1 fix: never set a px min-width here — it inflates tab min-content and spills the QAM
           horizontally. max-width stays none so a % parent cannot clip the glass. */
        .bonsai-scope .bonsai-askbar-row-host,
        .bonsai-scope .bonsai-ask-bleed-wrap .bonsai-askbar-merged {
          width: 100% !important;
          min-width: 0 !important;
          max-width: none !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
        }

        .bonsai-scope .bonsai-askbar-merged .bonsai-ask-primary.DialogButton,
        .bonsai-scope .bonsai-ask-bleed-wrap .Panel.Focusable {
          width: 100% !important;
          max-width: none !important;
          min-width: 0 !important;
        }

        .bonsai-scope .bonsai-ask-bleed-wrap,
        .bonsai-scope .bonsai-ask-bleed-wrap .bonsai-askbar-merged {
          flex: 1 1 auto !important;
          align-self: stretch !important;
        }


/* ==========================================================================
           5. UNIFIED INPUT FIELD & TEXT AREA STYLING
           Aggressively strips native styling from inputs so we can draw custom carets/overlays.
           ========================================================================== */
        /*
          Decky renders TextField inside a .Panel.Focusable wrapper (plus an inner div) that does
          not inherit our host width — the "wrappers diverge from host width" note the measuring in
          useUnifiedInputSurface was originally written around. Unwidened, the typing surface is
          narrower than the glass card holding it. The Ask row already forces the same wrapper to
          100% (section-4); this is the matching rule for the input host, which never had one.

          Scoped by :has(textarea) / :has(input) on purpose: the ask-mode and attach popovers are
          also .Panel.Focusable inside this host, contain no field, and must keep their own width.
        */
        .bonsai-scope .bonsai-unified-input-host .Panel.Focusable:has(textarea),
        .bonsai-scope .bonsai-unified-input-host .Panel.Focusable:has(input),
        .bonsai-scope .bonsai-unified-input-host .Panel.Focusable:has(textarea) > div,
        .bonsai-scope .bonsai-unified-input-host .Panel.Focusable:has(input) > div {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          padding-left: 0 !important;
          padding-right: 0 !important;
          box-sizing: border-box !important;
        }

        /*
          Same declarations without :has(), so the fix does not depend on it. An unsupported :has()
          invalidates the whole selector list above and CEF drops that rule silently.

          These reach the wrapper by position instead: direct child of the field layer (plain
          layout) or of .bonsai-unified-input-text-box (AI character layout). The popovers are
          excluded either way — .bonsai-ask-mode-menu-floater / .bonsai-attach-menu-floater are the
          direct children there, and their own .Panel.Focusable sits a level deeper inside them.
        */
        .bonsai-scope .bonsai-unified-input-host > div > .Panel.Focusable,
        .bonsai-scope .bonsai-unified-input-host > div > .Panel.Focusable > div,
        .bonsai-scope .bonsai-unified-input-text-box > .Panel.Focusable,
        .bonsai-scope .bonsai-unified-input-text-box > .Panel.Focusable > div {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          margin-left: 0 !important;
          margin-right: 0 !important;
          padding-left: 0 !important;
          padding-right: 0 !important;
          box-sizing: border-box !important;
        }

        .bonsai-scope .bonsai-unified-input-host input,
        .bonsai-scope .bonsai-unified-input-host textarea {
          width: 100% !important;
          max-width: 100% !important;
          min-width: 0 !important;
          color: transparent !important;
          -webkit-text-fill-color: transparent !important;
          margin: 0 !important;
          padding: calc(6px * var(--bonsai-ui-scale, 1)) calc(8px * var(--bonsai-ui-scale, 1)) calc(2px * var(--bonsai-ui-scale, 1)) calc(8px * var(--bonsai-ui-scale, 1)) !important;
          text-indent: 0 !important;
          box-sizing: border-box !important;
          font-size: calc(12px * var(--bonsai-ui-scale, 1)) !important;
          line-height: 1.2 !important;
          vertical-align: top !important;
        }

        /*
          The mirrors must copy the field's own wrapping and font stack, never declare their own
          (roadmap: "The question overlay sits a few pixels off the native text field") -- a
          mismatch here wraps a long line one character sooner than the real field does and drifts
          the caret/typed-text overlay off it. useUnifiedInputSurface.ts reads the live field's
          computed style on every measure pass and writes these three custom properties; the
          fallbacks below (matching the constants of the same name) only apply before that first
          pass has run.
        */
        .bonsai-scope .bonsai-unified-input-host .bonsai-unified-input-measure,
        .bonsai-scope .bonsai-unified-input-host .bonsai-unified-input-text-overlay {
          padding: calc(6px * var(--bonsai-ui-scale, 1)) calc(8px * var(--bonsai-ui-scale, 1)) calc(2px * var(--bonsai-ui-scale, 1)) calc(8px * var(--bonsai-ui-scale, 1)) !important;
          box-sizing: border-box !important;
          white-space: var(--bonsai-unified-field-white-space, pre-wrap) !important;
          overflow-wrap: var(--bonsai-unified-field-overflow-wrap, anywhere) !important;
          font-family: var(--bonsai-unified-field-font-family, inherit) !important;
        }

        .bonsai-scope .bonsai-unified-input-host.bonsai-unified-input--ai-character {
          overflow: hidden !important;
        }

        /* Avatar sits in a flex column beside the text box — not inside the field — so the native caret aligns with typed text. */
        .bonsai-scope .bonsai-unified-input-text-row {
          display: flex;
          flex-direction: row;
          align-items: flex-start;
          width: 100%;
          box-sizing: border-box;
        }
        .bonsai-scope .bonsai-ai-character-avatar-slot {
          position: relative;
          flex: 0 0 auto;
          width: 18px;
          height: 18px;
          margin: 2px 4px 0 2px;
          z-index: 6;
        }
        .bonsai-scope .bonsai-unified-input-text-box {
          position: relative;
          flex: 1 1 auto;
          min-width: 0;
          width: 100%;
          box-sizing: border-box;
        }

        .bonsai-scope .bonsai-ai-character-avatar {
          outline: none;
          margin: 0 !important;
          padding: 0 !important;
          box-sizing: border-box !important;
          opacity: 0.85 !important;
          overflow: hidden !important;
        }

        /* Matches the overlay span in section-6 (.bonsai-unified-input-strategy-placeholder):
           the field has two placeholder render paths and they have to read the same. */
        .bonsai-scope .bonsai-unified-input-host input::placeholder,
        .bonsai-scope .bonsai-unified-input-host textarea::placeholder {
          font-size: calc(12px * var(--bonsai-ui-scale, 1)) !important;
          font-style: italic !important;
          color: rgba(200, 214, 230, 0.45) !important;
        }

        /* Hide standard field labels to allow custom overlays */
        .bonsai-scope .bonsai-unified-input-host [class*="FieldLabel"],
        .bonsai-scope .bonsai-unified-input-host [class*="fieldlabel"] {
          display: none !important;
          height: 0 !important;
          min-height: 0 !important;
          margin: 0 !important;
          padding: 0 !important;
          overflow: hidden !important;
        }

        /* Position the fake text overlay to perfectly cover the invisible actual input */
        .bonsai-scope .bonsai-unified-input-text-overlay {
          margin: 0 !important;
          box-sizing: border-box !important;
          left: var(--bonsai-unified-field-left, 0px) !important;
          top: var(--bonsai-unified-field-top, 0px) !important;
          right: auto !important;
          width: var(--bonsai-unified-field-width, 100%) !important;
        }

        /*
         * The blinking cursor. The real field underneath is invisible, so the cursor is drawn: a
         * thin bar that sits IN the line of text, never at a fixed spot in the box. Whatever
         * places the text -- the field's padding, the text size, the line height, the UI scale --
         * places the cursor too, so a later change to any of them cannot leave it behind.
         *
         * It came loose exactly that way, more than once (roadmap bug, 2026-09-24). On the empty
         * box it was pinned to the overlay's corner (position absolute, left 0, top 0), which is
         * outside the overlay's 8px/6px padding, while the hint text starts inside it: measured on
         * the Deck, 5px left of the "D" and 4px above it. The fix before that matched font sizes,
         * and the check that closed it compared sizes, not positions, so it could not see this.
         *
         * It takes no room -- the negative right margin cancels its own width -- so nothing
         * beside it shifts or re-wraps when it appears or blinks, and the drawn text keeps
         * wrapping exactly where the real field underneath wraps. The em height is the fallback
         * for a runtime without the lh unit.
         */
        .bonsai-scope .bonsai-unified-input-fake-caret {
          display: inline-block;
          width: 1.5px;
          height: 1.2em;
          height: 1lh;
          margin: 0 -1.5px 0 0;
          vertical-align: top;
          background: currentColor;
          opacity: 0.9;
          transform: translateX(0.5px);
          animation: bonsai-caret-blink 1s step-end infinite;
        }

        /* Before the empty box's hint: its right edge the same half pixel clear of the "D". */
        .bonsai-scope .bonsai-unified-input-fake-caret--before-hint {
          transform: translateX(calc(-100% - 0.5px));
        }
        @keyframes bonsai-caret-blink {
          0%, 45% { opacity: 0.9; }
          50%, 100% { opacity: 0; }
        }


/* ==========================================================================
           6. GLASS PANELS & UI THEMING
           Applies frosted glass effects and borders to standard panels.
           ========================================================================== */
        .bonsai-scope .bonsai-glass-panel,
        .bonsai-scope .bonsai-preset-glass {
          -webkit-backdrop-filter: blur(10px);
          backdrop-filter: blur(10px);
          box-sizing: border-box;
        }

        .bonsai-scope .bonsai-glass-panel {
          background: rgba(18, 26, 34, 0.25) !important;
          border: 1px solid rgba(255, 255, 255, 0.07) !important;
        }

        @keyframes bonsai-ask-input-breathe {
          0%, 100% {
            border-color: var(--bonsai-ask-breathe-low, rgba(74, 222, 128, 0.28));
            box-shadow: 0 0 0 0 var(--bonsai-ask-glow-low, rgba(74, 222, 128, 0.05));
          }
          50% {
            border-color: var(--bonsai-ask-breathe-high, rgba(74, 222, 128, 0.72));
            box-shadow: 0 0 10px 2px var(--bonsai-ask-glow-high, rgba(74, 222, 128, 0.16));
          }
        }
        .bonsai-scope .bonsai-unified-input-host.bonsai-unified-input--asking.bonsai-glass-panel,
        .bonsai-scope .bonsai-unified-input-host.bonsai-unified-input--capturing.bonsai-glass-panel {
          animation: bonsai-ask-input-breathe 3.4s ease-in-out infinite;
        }
        /* While the answer's text is arriving, the glow holds steady -- the look reduced motion
           gets -- and breathes again for the next question's thinking. Measured on the Deck,
           2026-09-25: this breathing and the answer bubble's pulse cost the panel about 5 frames a
           second while an answer streamed in, and nothing while the model was only thinking. */
        .bonsai-scope .bonsai-main-tab-dock--answer-arriving .bonsai-unified-input-host.bonsai-unified-input--asking.bonsai-glass-panel {
          animation: none;
          border-color: var(--bonsai-ask-breathe-high, var(--bonsai-ask-mode-accent, #4ade80)) !important;
          box-shadow: 0 0 0 1px var(--bonsai-ask-glow-high, rgba(74, 222, 128, 0.2));
        }
        @media (prefers-reduced-motion: reduce) {
          .bonsai-scope .bonsai-unified-input-host.bonsai-unified-input--asking.bonsai-glass-panel,
          .bonsai-scope .bonsai-unified-input-host.bonsai-unified-input--capturing.bonsai-glass-panel {
            animation: none;
            border-color: var(--bonsai-ask-breathe-high, var(--bonsai-ask-mode-accent, #4ade80)) !important;
            box-shadow: 0 0 0 1px var(--bonsai-ask-glow-high, rgba(74, 222, 128, 0.2));
          }
        }

        /* Plan 60, board B, 2026-09-17: the chip should read as a pressable thing, not a flat
           label. A gradient (lighter at the top, darker at the bottom) plus a hairline on the top
           edge and a soft shadow underneath give it the "raised button" cue the flat 22 percent
           fill never had. The help chip and the agent chip below keep their own background and
           border for their own colour, but neither sets box-shadow, so this rule's hairline and
           shadow still reach them (D110, item 5) — they sit level with the other chips. */
        .bonsai-scope .bonsai-preset-glass {
          background: linear-gradient(180deg, rgba(56, 70, 84, 0.5) 0%, rgba(16, 22, 30, 0.55) 100%) !important;
          border: 1px solid rgba(255, 255, 255, 0.10) !important;
          box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, 0.10),
            0 2px 3px rgba(0, 0, 0, 0.4) !important;
        }

        .bonsai-scope button.bonsai-preset-help-chip.bonsai-preset-glass {
          background: linear-gradient(
            180deg,
            rgba(46, 135, 83, 0.28) 0%,
            rgba(18, 52, 34, 0.48) 100%
          ) !important;
          border: 1px solid var(--bonsai-ui-accent-main, rgba(46, 135, 83, 0.65)) !important;
          color: #dff5ea !important;
        }

        /* The agent chip keeps its own orange ring and glow, and gains the raised look with them
           (D110, item 5). The hairline and drop shadow from the rule above are written out again
           here because box-shadow replaces the whole list rather than adding to it. */
        .bonsai-scope button.bonsai-preset-glass.bonsai-pyro-inject-chip {
          border: 2px solid rgba(255, 107, 53, 0.92) !important;
          box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, 0.10),
            0 0 0 1px rgba(160, 45, 28, 0.5),
            0 0 12px rgba(255, 85, 40, 0.38),
            0 2px 3px rgba(0, 0, 0, 0.4) !important;
          background: rgba(38, 22, 18, 0.38) !important;
          color: #f0ddd6 !important;
        }

        /* Font size must match the real field's own text (UNIFIED_TEXT_FONT_PX, section-5.ts) --
           roadmap: "The blinking cursor in the question box does not line up with the placeholder
