          overflow: hidden !important;
          padding: calc(2px * var(--bonsai-ui-scale, 1)) calc(4px * var(--bonsai-ui-scale, 1)) calc(2px * var(--bonsai-ui-scale, 1)) calc(8px * var(--bonsai-ui-scale, 1)) !important;
          border-left: 2px solid rgba(159, 183, 213, 0.4) !important;
          margin-bottom: calc(8px * var(--bonsai-ui-scale, 1)) !important;
          min-width: 0 !important;
          font-size: calc(9px * var(--bonsai-ui-scale, 1)) !important;
          font-style: italic !important;
          line-height: 1.15 !important;
          color: rgba(180, 198, 217, 0.6) !important;
          white-space: pre-wrap !important;
          overflow-wrap: anywhere !important;
        }
        /*
         * The whole thinking, once the fold row above it has been opened. The answer chunk's own
         * dark surface, so it reads as a quieter neighbour of the answer rather than a second
         * answer. Line breaks are kept as the model wrote them, and nothing inside is masked.
         */
        .bonsai-scope .bonsai-chat-reasoning-block {
          width: 100% !important;
          box-sizing: border-box !important;
          background: rgba(18, 26, 34, 0.28) !important;
          border: 1px solid rgba(255, 255, 255, 0.08) !important;
          border-radius: calc(6px * var(--bonsai-ui-scale, 1)) !important;
          padding: calc(8px * var(--bonsai-ui-scale, 1)) !important;
          margin-bottom: calc(6px * var(--bonsai-ui-scale, 1)) !important;
          font-size: calc(11px * var(--bonsai-ui-scale, 1)) !important;
          line-height: 1.4 !important;
